const body = $json.body || {};
const query = $json.query || {};
const entry = body.entry?.[0] || {};
const objectType = body.object || '';

// Detectar verificación de webhook
const isVerify = !!query['hub.challenge'];
if (isVerify) {
  return [{ json: { isVerify: true, challenge: query['hub.challenge'] } }];
}

// Rama messaging (FB DM e IG DM)
const msg    = entry.messaging?.[0] || null;
// Rama changes (comentarios, reacciones)
const change = entry.changes?.[0]   || null;
const value  = change?.value        || {};

const hasMessaging = !!msg?.message?.text;
const isComment    = change?.field === 'feed' && value?.item === 'comment' && value?.verb === 'add';
const isReaction   = change?.field === 'feed' && value?.item === 'reaction';
const isFbDm       = objectType === 'page'      && hasMessaging;
const isIgDm       = objectType === 'instagram' && hasMessaging;

let eventType = 'unknown';
if      (isComment)            eventType = 'comment';
else if (isFbDm || isIgDm)     eventType = 'dm';
else if (isReaction)           eventType = 'reaction';

return [{json:{
  isVerify:     false,
  eventType,
  objectType,
  canal:        isIgDm ? 'instagram' : 'facebook',
  origen:       isIgDm ? 'Instagram DM' : (isFbDm ? 'Messenger FB' : (isComment ? 'FB Comentario' : 'Desconocido')),
  sender_id:    msg?.sender?.id   || value?.from?.id || '',
  sender_name:  value?.from?.name || '',
  recipient_id: msg?.recipient?.id || entry.id || '',
  text:         msg?.message?.text || value?.message || '',
  message_mid:  msg?.message?.mid  || '',
  post_id:      value?.post_id     || '',
  comment_id:   value?.comment_id  || '',
  reaction_type:value?.reaction_type || '',
  page_id:      entry.id           || '',
  raw_body:     body
}}];

const sri    = $json;
const prev   = $('IF Datos Completos').first().json;
const body   = JSON.stringify(sri).toLowerCase();
const activo = body.includes('activo');
return [{json:{
  ...prev,
  ruc_estado: activo ? 'ACTIVO' : (body.includes('inactivo') ? 'INACTIVO' : 'NO_ENCONTRADO'),
  ruc_activo: activo
}}];

const d = $input.first().json;

const empresaRaw     = d.empresa ?? d.Empresa ?? '';
const correoRaw      = d.correo ?? d.Correo ?? '';
const telefonoRaw    = d.telefono ?? d.Teléfono ?? '';
const industriaRaw   = d.industria ?? d.Industria ?? '';
const usuariosRaw    = d.usuarios ?? d.Usuarios ?? '';
const facturacionRaw = d.facturacion ?? d.Facturación ?? '';

let score = 0;

const norm = (s) => String(s || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const rucActivo = String(d.ruc_estado || '').toUpperCase() === 'ACTIVO';
const empresaInvalida = ['test','prueba','na','123','none'].includes(norm(empresaRaw));
const telefonoOk = /^(?:\+?593|593|52|58|1)\d+/.test(String(telefonoRaw).replace(/\s+/g, ''));

if (!rucActivo || empresaInvalida || !telefonoOk) {
  return [{
    json: {
      ...d,
      score: 0,
      resultado_final: 'No pasa',
      nota: 'Falla requisito obligatorio'
    }
  }];
}

score += 20;
score += empresaInvalida ? 0 : 5;

const correo = String(correoRaw || '');
if (correo && !/@(gmail|hotmail|outlook|yahoo)\./i.test(correo)) score += 15;
else if (correo) score += 5;

const industriasCalif = ['consumo masivo','farma','farmaceutica','ferreteria','automotriz','agro'];
if (industriasCalif.includes(norm(industriaRaw))) score += 10;
else if (industriaRaw) score += 5;

score += 5;

const usr = norm(usuariosRaw);
if (/mas de 20|\+20|20\+/.test(usr)) score += 15;
else if (/(?:^|[^0-9])(5|6|7|8|9|1[0-9]|20)(?:[^0-9]|$)/.test(usr)) score += 10;
else if (/^([1-4])$/.test(usr) || /1\s*-\s*4/.test(usr)) score += 5;

const fact = norm(facturacionRaw);
if (/mas de 2|2m|2000000/.test(fact)) score += 8;
else if (/500.*2m|500.*2|500000.*2000000/.test(fact)) score += 7;
else if (/100.*500|100000.*500000/.test(fact)) score += 5;

const resultado = score >= 50 ? 'MQL' : 'Nurturing frio';

return [{
  json: {
    ...d,
    score,
    resultado_final: resultado
  }
}];

